// Maestro Dialog Agent — proxy přes MCP /maestro/chat (service-role).
//
// VAROVÁNÍ: Tento workflow je low-level proxy pro n8n agenty s service-role tokenem.
// Standardní cesta z frontendu je svc-ai-chat /story-consult orchestrace s plným
// brain wiringem (Tao + Psyche + Hippocampus + governance + compose_context).
// Pro user-facing dialogy vždy použij /story-consult endpoint.
//
// Body: { project_id?, session_id?, message, system_prompt?, history?, lang? }
const body = $input.item.json.body || {};
const projectId = body.project_id || 'aisha';
const message = body.message || body.text || '';
const history = body.history || [];
const systemPrompt = body.system_prompt || '';
const lang = body.lang || 'cs-CZ';

if (!message) {
  return { json: { error: 'Missing message in request body' } };
}

return {
  json: {
    project_id: projectId,
    session_id: body.session_id || 'maestro-' + Date.now(),
    message,
    history,
    system_prompt: systemPrompt,
    lang,
  }
};

