// Format Maestro response s metadata pro callers (n8n agents, sandbox tests).
const maestroData = $input.item.json.data || $input.item.json;
const answer = maestroData.answer || maestroData.response || maestroData.generated_text || maestroData.message || '';

return {
  json: {
    signal: 'maestro_dialog_result',
    action: 'multi_turn_chat',
    answer,
    metadata: {
      provider: 'maestro',
      project_id: $('Prepare Input').item.json.project_id,
      session_id: $('Prepare Input').item.json.session_id,
      multi_turn_coherence: 'alquist-insight-alexa-prize',
    },
    raw: maestroData,
  }
};
